// Runs only on whichever peer currently holds host_epoch (SPEC.md
// sections 3 and 6). Wraps the WASM physics-core module, runs the fixed
// timestep sim loop, and hands snapshot/resolution data up to RoomManager
// to broadcast. Non-host clients never instantiate this class.
//
// Build note: this expects wasm-pack output at
// packages/physics-core/pkg/physics_core.js (run `wasm-pack build --target
// web` in packages/physics-core — see root README). Adjust the import path
// below if you wire up bundling differently.

// @ts-ignore - generated by wasm-pack, not present until physics-core is built
import init, { Simulation } from "../../../physics-core/pkg/physics_core.js";
import type { DiscState } from "../network/protocol";

const PHYSICS_TICK_HZ = 60;
const PHYSICS_DT = 1 / PHYSICS_TICK_HZ;
const SNAPSHOT_RATE_HZ = 25; // SPEC.md section 4: ~20-30Hz

export interface ResolvedShotResult {
  pocketedDiscIds: number[];
  discs: DiscState[];
  nextPlayerId: string;
}

export class HostSimulation {
  private sim: any; // Simulation, once wasm module is initialized
  private ready: Promise<void>;
  private accumulator = 0;
  private lastFrameTime = 0;
  private timeSinceSnapshot = 0;
  private awaitingResolution = false;
  private playerOrder: string[];
  private currentPlayerIndex = 0;

  constructor(
    playerOrder: string[],
    private onSnapshot: (discs: DiscState[]) => void,
    private onResolved: (result: ResolvedShotResult) => void,
  ) {
    this.playerOrder = playerOrder;
    this.ready = init().then(() => {
      this.sim = new Simulation();
    });
  }

  async waitUntilReady() {
    await this.ready;
  }

  getCurrentPlayerId(): string {
    return this.playerOrder[this.currentPlayerIndex];
  }

  /** Reconstruct from a last-known snapshot after host migration, rather
   * than trying to resurrect exact in-flight physics (SPEC.md section 6).
   * Uses wasm `set_discs` to load exact resting layout — "void and retake"
   * for mid-shot drops (velocities zeroed in Rust). */
  seedFromLastKnownState(discs: DiscState[], playerOrder: string[], currentPlayerId: string) {
    this.playerOrder = playerOrder;
    this.currentPlayerIndex = Math.max(0, playerOrder.indexOf(currentPlayerId));
    if (this.sim?.set_discs) {
      this.sim.set_discs(discs);
    } else {
      // WASM not ready yet — queue until it is
      this.ready.then(() => this.sim?.set_discs(discs));
    }
    this.awaitingResolution = false;
  }

  setStrikerPosition(x: number, y: number) {
    this.sim?.set_striker_position(x, y);
  }

  applyShot(angle: number, power: number) {
    if (this.awaitingResolution) return; // ignore input mid-resolution
    this.sim?.apply_shot(angle, power);
    this.awaitingResolution = true;
  }

  /** Call every animation frame; internally steps physics at a fixed
   * timestep and throttles snapshot emission independently (SPEC.md
   * section 4). */
  update(nowMs: number) {
    if (!this.sim) return;
    if (this.lastFrameTime === 0) this.lastFrameTime = nowMs;
    const frameDt = (nowMs - this.lastFrameTime) / 1000;
    this.lastFrameTime = nowMs;
    this.accumulator += frameDt;

    while (this.accumulator >= PHYSICS_DT) {
      this.sim.step(PHYSICS_DT);
      this.accumulator -= PHYSICS_DT;
    }

    this.timeSinceSnapshot += frameDt;
    if (this.timeSinceSnapshot >= 1 / SNAPSHOT_RATE_HZ) {
      this.timeSinceSnapshot = 0;
      this.onSnapshot(this.currentSnapshot());
    }

    if (this.awaitingResolution && this.sim.is_settled()) {
      this.awaitingResolution = false;
      this.resolveShot();
    }
  }

  public getSnapshot(): DiscState[] {
    return this.sim ? (this.sim.snapshot() as DiscState[]) : [];
  }

  private currentSnapshot(): DiscState[] {
    return this.getSnapshot();
  }

  private resolveShot() {
    const pocketedDiscIds: number[] = Array.from(this.sim.take_pocketed_events());
    let discs = this.currentSnapshot();
    discs = this.applyFoulAndQueenRules(pocketedDiscIds, discs);
    this.advanceTurn(pocketedDiscIds, discs);
    // Always reposition striker to next player's baseline (fixes "striker doesn't shift" — Spec baseline rule)
    discs = this.repositionStrikerToBaseline(discs);
    this.sim?.set_discs(discs);
    discs = this.currentSnapshot();
    this.onResolved({
      pocketedDiscIds,
      discs,
      nextPlayerId: this.getCurrentPlayerId(),
    });
  }

  private applyFoulAndQueenRules(pocketedIds: number[], discs: DiscState[]): DiscState[] {
    const BOARD_CENTER = 340;
    const BOARD_SIZE = 680;
    const has = (id: number) => pocketedIds.includes(id);
    const byId = new Map(discs.map((d) => [d.id, d]));

    // Striker foul: respawn striker at baseline for next shot
    if (has(19)) {
      const striker = byId.get(19);
      if (striker) {
        striker.active = true;
        striker.x = BOARD_CENTER;
        striker.y = BOARD_SIZE - 60;
        striker.vx = 0;
        striker.vy = 0;
      }
    }

    // Queen cover rule: queen pocketed without also pocketing own coin => return queen to center
    if (has(0)) {
      const myColor = this.getPlayerColor(this.currentPlayerIndex);
      const pocketedOwn = pocketedIds.some((id) => {
        const d = byId.get(id);
        return d?.disc_type === myColor;
      });
      if (!pocketedOwn) {
        const queen = byId.get(0);
        if (queen) {
          queen.active = true;
          queen.x = BOARD_CENTER;
          queen.y = BOARD_CENTER;
          queen.vx = 0;
          queen.vy = 0;
        }
      }
    }
    return discs;
  }

  private advanceTurn(pocketedIds: number[], discs: DiscState[]) {
    const byId = new Map(discs.map((d) => [d.id, d]));
    const hasStrikerFoul = pocketedIds.includes(19);
    const myColor = this.getPlayerColor(this.currentPlayerIndex);

    // Striker foul = immediate turn loss
    if (hasStrikerFoul) {
      this.currentPlayerIndex = (this.currentPlayerIndex + 1) % this.playerOrder.length;
      return;
    }

    // Check what was pocketed this shot (before reactivation)
    const pocketedOwn = pocketedIds.some((id) => {
      const d = byId.get(id);
      return d?.disc_type === myColor;
    });
    const hasOpponentCoin = pocketedIds.some((id) => {
      const d = byId.get(id);
      return d && (d.disc_type === "black" || d.disc_type === "white") && d.disc_type !== myColor;
    });
    // But note queen was already handled — pocketedTypes includes queen
    const hasOnlyOwnAndQueen = pocketedOwn && !hasOpponentCoin;

    // Real carrom: pocket own coin (+ optionally queen with cover) => retain turn
    if (hasOnlyOwnAndQueen) {
      return; // keep current player
    }
    if (hasOpponentCoin) {
      // Foul: pocketing opponent's coin => turn loss (queen already returned if needed)
      this.currentPlayerIndex = (this.currentPlayerIndex + 1) % this.playerOrder.length;
      return;
    }
    if (pocketedOwn) {
      return; // retain
    }
    // No pocket or only queen without cover (already returned) => next player
    this.currentPlayerIndex = (this.currentPlayerIndex + 1) % this.playerOrder.length;
  }

  private getPlayerColor(index: number): "black" | "white" {
    // 2 players: p0 black, p1 white. 3-4 players: alternating teams
    return index % 2 === 0 ? "black" : "white";
  }

  private repositionStrikerToBaseline(discs: DiscState[]): DiscState[] {
    const BOARD = 680;
    const CENTER = BOARD / 2;
    const BASELINE_OFFSET = 60;
    const n = this.playerOrder.length;
    const idx = this.currentPlayerIndex;
    const striker = discs.find((d) => d.id === 19);
    if (!striker) return discs;
    striker.active = true;
    striker.vx = 0;
    striker.vy = 0;
    // Map player index to side (clockwise from south). For 2 players: south/north only.
    if (n === 2) {
      striker.x = CENTER;
      striker.y = idx === 0 ? BOARD - BASELINE_OFFSET : BASELINE_OFFSET;
    } else {
      // 3-4 players: 0=south, 1=west, 2=north, 3=east
      switch (idx % 4) {
        case 0: striker.x = CENTER; striker.y = BOARD - BASELINE_OFFSET; break;
        case 1: striker.x = BASELINE_OFFSET; striker.y = CENTER; break;
        case 2: striker.x = CENTER; striker.y = BASELINE_OFFSET; break;
        case 3: striker.x = BOARD - BASELINE_OFFSET; striker.y = CENTER; break;
      }
    }
    return discs;
  }

  /** Sync turn/order after a forfeit without a shot (SPEC.md §7). */
  syncPlayerState(playerOrder: string[], currentPlayerId: string) {
    this.playerOrder = playerOrder;
    const idx = playerOrder.indexOf(currentPlayerId);
    this.currentPlayerIndex = idx >= 0 ? idx : 0;
  }

  setPaused(_paused: boolean) {
    // Placeholder for future: freeze accumulator while paused
    // Currently host loop still runs but shots are ignored via awaitingResolution guard
  }
}
